import pandas as pd
import numpy as np
import statsmodels.api as sm

def estimate(df, ctx):
    cols_needed = ['y', 'campaign', 'job_management', 'job_technician', 'job_entrepreneur', 'job_blue-collar', 'job_admin.', 'job_services', 'job_retired', 'job_self-employed', 'job_unemployed', 'job_housemaid', 'job_student', 'marital_married', 'marital_single', 'education_secondary', 'education_tertiary', 'default_yes', 'housing_yes', 'loan_yes', 'contact_telephone', 'month_jan', 'month_feb', 'month_mar', 'month_apr', 'month_may', 'month_jun', 'month_jul', 'month_aug', 'month_sep', 'month_oct', 'month_nov', 'month_dec', 'poutcome_other', 'poutcome_success', 'balance', 'age', 'day_of_week', 'duration', 'pdays', 'previous']
    data = df.dropna(subset=cols_needed)
    n = len(data)
    if n == 0:
        return {"estimate": np.nan, "ci_low": np.nan, "ci_high": np.nan, "p_value": np.nan, "n": n}

    X = pd.DataFrame()
    X['campaign'] = data['campaign'].astype(float)
    for col in cols_needed:
        if col != 'y' and col != 'campaign' and col in data.columns:
            X[col] = data[col].astype(float)

    if not np.isfinite(X.values).all():
        X = X.replace([np.inf, -np.inf], np.nan)
        valid_idx = X.dropna().index
        X = X.loc[valid_idx]
        y = data['y'].loc[valid_idx].astype(float)
        if len(X) == 0:
            return {"estimate": np.nan, "ci_low": np.nan, "ci_high": np.nan, "p_value": np.nan, "n": 0}
    else:
        y = data['y'].astype(float)

    if not np.isfinite(X.values).all() or not np.isfinite(y.values).all():
        return {"estimate": np.nan, "ci_low": np.nan, "ci_high": np.nan, "p_value": np.nan, "n": len(X)}

    X = sm.add_constant(X, has_constant='add')
    model = sm.Logit(y, X)
    result = model.fit(cov_type='HC0', disp=False)
    campaign_coef = result.params['campaign']
    campaign_se = result.bse['campaign']
    estimate = np.exp(campaign_coef)
    ci_low = np.exp(campaign_coef - 1.96 * campaign_se)
    ci_high = np.exp(campaign_coef + 1.96 * campaign_se)
    p_value = result.pvalues['campaign']
    return {"estimate": float(estimate), "ci_low": float(ci_low), "ci_high": float(ci_high), "p_value": float(p_value), "n": len(X)}

